import React, { useState, useEffect, useRef } from "react";
import { Link } from "react-router-dom";
import "./Navbar.css";
import logo from "../logo.jpeg";

function Navbar() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [moreOpen, setMoreOpen] = useState(false);
  const moreRef = useRef(null);

  const closeMenu = () => {
    setMenuOpen(false);
    setMoreOpen(false);
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (moreRef.current && !moreRef.current.contains(event.target)) {
        setMoreOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  return (
    <header className="main-navbar">
      <div className="navbar-inner">

        {/* LOGO */}
        <Link to="/" className="brand-logo" onClick={closeMenu}>
          <img
            src={logo}
            alt="Noida Extension Property"
            className="logo-image"
          />
        </Link>

        {/* DESKTOP / MOBILE MENU */}
        <nav className={`nav-links ${menuOpen ? "open" : ""}`}>

          <Link to="/" onClick={closeMenu}>
            Home
          </Link>

          <Link to="/our-journey" onClick={closeMenu}>
            Projects
          </Link>

           <Link to="/loan" onClick={closeMenu}>
            Apply Loan
          </Link>

          <Link to="/contact" onClick={closeMenu}>
            Contact Us
          </Link>

          <Link to="/services" onClick={closeMenu}>
            About
          </Link>

          {/* MORE DROPDOWN */}
          <div className="more-dropdown" ref={moreRef}>

            <button
              className="more-button"
              onClick={() => setMoreOpen(!moreOpen)}
            >
              More
              <span className={moreOpen ? "arrow rotate" : "arrow"}>
                ▾
              </span>
            </button>

            {moreOpen && (
              <div className="more-menu">

                <Link
                  to="/login?role=post-property"
                  onClick={closeMenu}
                >
                  <span>🏠</span>
                  Post Property
                </Link>

                <Link
                  to="/login?role=dashboard"
                  onClick={closeMenu}
                >
                  <span>📊</span>
                  Dashboard
                </Link>

              </div>
            )}

          </div>

        </nav>

        {/* MOBILE BUTTON */}
        <button
          className="mobile-menu"
          onClick={() => setMenuOpen(!menuOpen)}
          aria-label="Open menu"
        >
          {menuOpen ? "×" : "☰"}
        </button>

      </div>
    </header>
  );
}

export default Navbar;
